import assert from "node:assert/strict";
import {createElement} from "react";
import {renderToStaticMarkup} from "react-dom/server";
import type {Block} from "../../src/core/types";
import type {GeneratedBody} from "../../src/core/generators/definition";
import {Legacy2018AutumnFoundationsFigure} from "../../src/ui/Legacy2018AutumnFoundationsFigures";
import {legacy2018AutumnMathFacts as facts} from "./legacy-2018-autumn-foundations-math-review";
const attr=(s:string,key:string)=>{const m=s.match(new RegExp(`(?:^|\\s)${key}="([^"]*)"`));assert(m);return m[1];},nums=(s:string,keys:string[])=>keys.map(k=>Number(attr(s,k)));
const para=(b:Block)=>{assert(b.type==="paragraph");return b.text;},choices=(b:GeneratedBody)=>b.choices.map(bs=>{assert.equal(bs.length,1);return para(bs[0]);});
export function legacy2018AutumnNetworkSvg(b:Block){assert(b.type==="diagram"&&b.scene.kind==="source_figure");return renderToStaticMarkup(createElement(Legacy2018AutumnFoundationsFigure,{profile:b.scene.profile,values:b.scene.values,caption:b.caption??""}));}
/** Actual endpoints, solid/dashed paths and visible city labels establish the
 * network; data-city/link names alone cannot substitute for the drawing. */
export function legacy2018ReadAutumnNetwork(svg:string){const groups=[...svg.matchAll(/<g data-city="([^"]*)">([\s\S]*?)<\/g>/g)];assert.equal(groups.length,3);for(const [i,m]of groups.entries()){const f=facts.availability.cities[i],ellipse=m[2].match(/<ellipse\b([^>]*)/),text=m[2].match(/<text\b([^>]*)>([^<]*)<\/text>/);assert(ellipse&&text);assert.equal(m[1],f.name);assert.deepEqual(nums(ellipse[1],["cx","cy","rx","ry"]),[f.x,f.y,55,27]);assert.equal(attr(ellipse[1],"fill"),"var(--surface)");assert.equal(text[2],f.name);assert.deepEqual(nums(text[1],["x","y"]),[f.x,f.y]);assert.equal(attr(text[1],"text-anchor"),"middle");}const lines=[...svg.matchAll(/<line\b([^>]*)/g)];assert.equal(lines.length,3);return lines.map((m,i)=>{const f=facts.availability.links[i];assert.equal(attr(m[1],"data-link"),f.id);const endpoints=nums(m[1],["x1","y1","x2","y2"]);assert.deepEqual(endpoints,[...f.from,...f.to]);if(f.dashed)assert.equal(attr(m[1],"stroke-dasharray"),"7 5");else assert(!m[1].includes("stroke-dasharray"));return{from:facts.availability.cities.find(c=>c.x===endpoints[0]&&c.y===endpoints[1])!.name,to:facts.availability.cities.find(c=>c.x===endpoints[2]&&c.y===endpoints[3])!.name};});}
/** Decimal probability numerator from every physical edge up/down state,
 * separately testing graph connectivity. Production uses complement formula. */
export function legacy2018NetworkNumerator(edges:{from:string;to:string}[],rate:number){let numerator=0;for(let state=0;state<8;state++){let probability=1;const reachable=new Set(["東京"]);edges.forEach((e,i)=>{probability*=state&(1<<i)?rate:10-rate;});for(let pass=0;pass<3;pass++)edges.forEach((e,i)=>{if(!(state&(1<<i)))return;if(reachable.has(e.from))reachable.add(e.to);if(reachable.has(e.to))reachable.add(e.from);});if(reachable.has("福岡"))numerator+=probability;}return numerator;}
/** Event boundaries determine completion/ready times; no production tick
 * simulator is imported. The returned idle slots cover only start..last end. */
export function legacy2018IndependentIdle(d:number[][]){const tasks=d.map(row=>({phase:0,left:row[0],until:Infinity})),slots:number[]=[],runs:{start:number;end:number;task:number}[]=[];let t=0;while(tasks.some(q=>q.phase!==3)){const cpu=tasks.findIndex(q=>q.phase===0||q.phase===2),end=Math.min(cpu>=0?t+tasks[cpu].left:Infinity,...tasks.filter(q=>q.phase===1).map(q=>q.until));assert(Number.isFinite(end)&&end>t);if(cpu<0)for(let s=t;s<end;s++)slots.push(s);else{runs.push({start:t,end,task:cpu});tasks[cpu].left-=end-t;if(tasks[cpu].left===0){if(tasks[cpu].phase===0){tasks[cpu].phase=1;tasks[cpu].until=end+d[cpu][1];}else tasks[cpu].phase=3;}}tasks.forEach((q,i)=>{if(q.phase===1&&q.until===end){q.phase=2;q.left=d[i][2];q.until=Infinity;}});t=end;assert(t<100);}return{elapsed:t,slots,runs};}
export function legacy2018AutumnMathOracle(source:string,b:GeneratedBody,v:number[]){assert.equal(b.choices.length,4);const alternatives=choices(b);let answer:number;
 if(source===facts.bit.source){assert.deepEqual(b.prompt.map(para),[facts.bit.stem,...facts.bit.steps]);assert.equal(v.length,2);assert(v.every(n=>n===0||n===1));assert.deepEqual(alternatives,[facts.bit.wrongPairs[0][v[0]],facts.bit.wrongPairs[1][v[1]],facts.bit.originalChoices[2],facts.bit.originalChoices[3]]);const names=alternatives.map(s=>{const m=s.match(/（([A-Z]+)）/);assert(m);return m[1] as keyof typeof facts.bit.operatorTruth;}),truth=names.map(name=>{const op=facts.bit.operatorTruth[name];assert(op);for(let width=1;width<=10;width++)for(let a=1;a<2**width;a++){const bits=a.toString(2).padStart(width,"0").split("").map(Number),minus=(a-1).toString(2).padStart(width,"0").split("").map(Number),xor=bits.map((n,i)=>n===minus[i]?0:1),actual=bits.map((n,i)=>op[n*2+xor[i]]),target=bits.map((_,i)=>i===bits.lastIndexOf(1)?1:0);if(actual.some((n,i)=>n!==target[i]))return false;}return true;});assert.equal(truth.filter(Boolean).length,1);answer=truth.indexOf(true);for(const term of["B=00100111","C=00001111","A AND C=00001000","最も右の1だけ"])assert(b.explanation.includes(term));}
 else if(source===facts.availability.source){assert.equal(v.length,1);const rate=facts.availability.rates[v[0]];assert(rate);assert.equal(b.prompt.length,3);assert.equal(para(b.prompt[0]),`東京と福岡を結ぶ実線の回線がある。東京と福岡の間の信頼性を向上させるために、大阪を経由する破線の迂回回線を追加した。迂回回線追加後における、東京と福岡の間の稼働率は幾らか。ここで、回線の稼働率は、東京と福岡、東京と大阪、大阪と福岡の全てが${(rate/10).toFixed(1)}とする。`);assert.equal(para(b.prompt[1]),facts.availability.extraPremise);const edges=legacy2018ReadAutumnNetwork(legacy2018AutumnNetworkSvg(b.prompt[2]));const correct=legacy2018NetworkNumerator(edges,rate),numbers=alternatives.map(s=>{assert(/^0\.\d{3}$/.test(s));return Number(s.replace(".",""));});assert.deepEqual(numbers,[rate**3,rate*rate*10,correct,1000-(10-rate)**3]);assert.equal(new Set(numbers).size,4);answer=numbers.indexOf(correct);assert(numbers.filter(n=>n!==correct).every(n=>Math.abs(n-correct)/correct>=9/981));for(const term of[`${(correct/1000).toFixed(3)}`,"独立","2区間が両方","共通原因"])assert(b.explanation.includes(term));}
 else{assert.equal(source,facts.idle.source);assert.equal(v.length,1);const d=facts.idle.durations[v[0]];assert(d);assert.equal(b.prompt.length,3);assert.equal(para(b.prompt[0]),facts.idle.stem);assert.equal(para(b.prompt[1]),facts.idle.policy);const table=b.prompt[2];assert(table.type==="table");assert.equal(table.caption,"単独実行時の動作順序と処理時間（ミリ秒）");assert.deepEqual(table.columns,["優先度","単独実行時の動作順序と処理時間（ミリ秒）"]);assert.deepEqual(table.rows,d.map((r,i)=>[["高","中","低"][i],`CPU(${r[0]}) → I/O(${r[1]}) → CPU(${r[2]})`]));const solved=legacy2018IndependentIdle(d);assert.deepEqual(solved.slots,facts.idle.slots[v[0]]);assert.equal(solved.slots.length,facts.idle.idle[v[0]]);assert.deepEqual(alternatives.map(Number),facts.idle.choices[v[0]]);answer=alternatives.indexOf(String(solved.slots.length));assert.equal(new Set(alternatives).size,4);assert.equal(solved.elapsed-d.reduce((n,r)=>n+r[0]+r[2],0),solved.slots.length);assert(alternatives.map(Number).filter(n=>n!==solved.slots.length).every(n=>Math.abs(n-solved.slots.length)/solved.slots.length>=1/6));assert(b.explanation.includes(`=${solved.slots.length}ミリ秒`));assert(b.explanation.includes(`全タスクは${solved.elapsed}ミリ秒で終了`));}
 assert.equal(b.correctIndex,answer);return answer;
}
